class ProfileScreen extends ConsumerWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context,WidgetRef ref){final p=ref.watch(progressProvider);return Scaffold(appBar:AppBar(title:const Text('ملفي')),body:ListView(padding:const EdgeInsets.all(20),children:[const CircleAvatar(radius:36,child:Icon(Icons.person,size:36)),const SizedBox(height:16),const Center(child:Text('قارئ BookSoul',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),const SizedBox(height:20),Row(children:[_stat('6','كتب'),_stat('12','ساعة'),_stat('${p.length}','قيد القراءة')]),const SizedBox(height:24),const Text('متابعة القراءة',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...demoBooks.take(3).map((b)=>ListTile(title:Text(b.title),subtitle:LinearProgressIndicator(value:p[b.id]??0),trailing:Text('${((p[b.id]??0)*100).round()}%')))]));} Widget _stat(String a,String b)=>Expanded(child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[Text(a,style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),Text(b)])))); }
